// spec: .qa/e2e/specs/organizations-landing.md
// seed: tests/seed.company.spec.ts
import { test, expect } from '@playwright/test';
import path from 'path';

test.use({ storageState: path.join(__dirname, '../../../auth/company.json') });

test.describe('/organizations — «publish tender» CTAs by role', () => {
  test('Logged-in company: every CTA opens the tender wizard (HE)', async ({ page }) => {
    // 1. Open /organizations (Hebrew). The header shows «לוח בקרה» (logged in).
    await page.goto('/organizations');
    await expect(page.getByRole('link', { name: 'לוח בקרה' })).toBeVisible();

    const ctas = page.locator('a[href="/publish/tender"]');
    await expect(ctas).toHaveCount(3);
    await expect(ctas.nth(0)).toHaveText('פרסמו מכרז עכשיו');
    await expect(ctas.nth(1)).toHaveText('פרסמו מכרז עכשיו');
    await expect(ctas.nth(2)).toHaveText('פרסום מכרז באתר');

    // 2-4. Click every CTA (hero, «איך מפרסמים מכרז?», bottom banner); go back to /organizations between clicks
    for (let i = 0; i < 3; i++) {
      if (i > 0) {
        await page.goto('/organizations');
      }
      await ctas.nth(i).scrollIntoViewIfNeeded();
      await ctas.nth(i).click();

      // Expected: tender wizard step 1, never registration. The wizard is not completed.
      await expect(page).toHaveURL(/\/publish\/tender$/);
      await expect(page).not.toHaveURL(/\/register/);
      await expect(page.getByText('שלב 1 מתוך 4')).toBeVisible();
      await expect(page.getByRole('heading', { level: 1, name: 'איזה כיף שבחרתם לפרסם מכרז אצלנו!' })).toBeVisible();
      await expect(page.getByRole('radio')).toHaveCount(2);
      await expect(page.getByRole('button', { name: 'המשך' })).toBeVisible();
    }
  });
});
